use crate::domains::kernel_opt::corpus::KernelRule;

/// Data table, not logic -- grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // ── A: accumulate in a j-major buffer so MAC stores are contiguous;
        // the i-major dst is written ONCE through a 16x8 register
        // transpose at the end. ────────────────────────────────────────
        KernelRule {
            rule_id: "jmajor-acc-buffer-transpose-writeback".to_string(),
            gpu_concept: "MECHANISM (accumulator layout): accumulate a tiled matmul block in a J-MAJOR buffer (row stride buf_stride) so every multiply-accumulate partial store is CONTIGUOUS, then write the finished block back to the I-MAJOR output through one register-transpose pass -- instead of accumulating straight into the i-major dst where every element store strides the column pitch while the accumulator walks j. SOURCE (ggml-org/llama.cpp @ d834d44e, tiled.cpp, verbatim): '// Writeback of the 256x256 window: buf is j-major (row stride buf_stride), dst is i-major (column stride dst_stride).' (tiled.cpp:679) + the 16x8 block moves as ONE register transpose -- load j-major rows then store transposed: 'float r[16][8];' with 'r[t][u] = buf[(ri + t) * buf_stride + rj + u];' then 'dst[(ri + t) + (size_t) (rj + u) * dst_stride] = r[t][u];' (tiled.cpp:686-695, the u-outer/t-inner store loop is the transpose). The transpose rides in REGISTERS (r[16][8] stays register-resident between the two loops) -- the strided dst writes happen ONCE per finished block, never per partial. REGIME: tiled matmul whose accumulate phase walks one axis faster than the output layout's stride axis (i-major dst, j-walking accumulator); blocks small enough for one register-resident transpose window (16x8 here). ANTI-REGIME: the output is already j-major -- store directly, the buffer and transpose are pure overhead; blocks too big for the register window (spill the transpose and the win is gone). KINSHIP (do not double-count): c-fragment-to-a-operand-register-repack = the same register-transpose shape, OPPOSITE direction (they repack FOR the MAC operand, this repacks FOR the store); stage-operand-mac-layout-inplace-transpose-at-repack (Batch 186) = the same j-major-for-contiguity idea at the STAGED OPERAND, this is the ACCUMULATOR side. CITE: ggml-org/llama.cpp @ d834d44e -- ggml/src/ggml-cpu/tiled/tiled.cpp:679 + 686-695. Batch 187 / Plan 183 / Research 218 (staged S1).".to_string(),
            ref_shape: "// NAIVE: accumulate straight into the I-MAJOR output. Every\n// element store strides the column pitch (dst_stride) while the\n// accumulator walks j -- the hot loop is strided stores.\nconst MI: usize = 16;\nconst MJ: usize = 8;\n\npub fn accumulate_into_dst(\n    mac_block: &[[f32; MJ]; MI],\n    dst: &mut [f32],\n    dst_stride: usize,\n    ri: usize,\n    rj: usize,\n) {\n    for t in 0..MI {\n        for u in 0..MJ {\n            // i-major element store: consecutive u stride dst_stride\n            dst[(ri + t) + (rj + u) * dst_stride] += mac_block[t][u];\n        }\n    }\n}".to_string(),
            opt_pattern: "// OPT: the accumulator is a J-MAJOR scratch (row stride\n// buf_stride) -- every element store is contiguous -- and ONE\n// register-resident transpose moves the finished 16x8 block to the\n// i-major dst (u-outer/t-inner store loop = the transpose).\nconst MI: usize = 16;\nconst MJ: usize = 8;\n\npub fn accumulate_jmajor(\n    mac_block: &[[f32; MJ]; MI],\n    buf: &mut [f32],\n    buf_stride: usize,\n    ri: usize,\n    rj: usize,\n) {\n    for t in 0..MI {\n        for u in 0..MJ {\n            // j-major: consecutive u are contiguous\n            buf[(ri + t) * buf_stride + rj + u] += mac_block[t][u];\n        }\n    }\n}\n\npub fn writeback_transposed(\n    buf: &[f32],\n    buf_stride: usize,\n    dst: &mut [f32],\n    dst_stride: usize,\n    ri: usize,\n    rj: usize,\n) {\n    // load the 16x8 block once (j-major rows) ...\n    let mut r = [[0.0f32; MJ]; MI];\n    for t in 0..MI {\n        for u in 0..MJ {\n            r[t][u] = buf[(ri + t) * buf_stride + rj + u];\n        }\n    }\n    // ... store transposed (i-major columns); u-outer = the transpose\n    for u in 0..MJ {\n        for t in 0..MI {\n            dst[(ri + t) + (rj + u) * dst_stride] = r[t][u];\n        }\n    }\n}".to_string(),
        },

        // ── B: partition the 16-row microtile into 8-row band passes sized
        // to the register file; the MAC-independent correction term runs
        // AFTER the band pass, adding no register pressure. ────────────
        KernelRule {
            rule_id: "register-budget-band-partition-indep-correction-offband".to_string(),
            gpu_concept: "MECHANISM (register-budget partitioning): when a microtile pass must hold more live accumulators than the register file, partition the pass into BANDS sized to the budget, and move any accumulator INDEPENDENT of the band's MAC results OUT of the band pass entirely -- it runs AFTER the bands and adds zero pressure. SOURCE (ggml-org/llama.cpp @ d834d44e, tiled-kernel.cpp, verbatim): '// Register pressure: the band pass holds acc16 + s1_acc = 16 zmm for the / 8-row band (s2_acc has no dpbusd dependency, so it is computed after the / band pass and adds no register pressure);' (tiled-kernel.cpp:91-93) + the offband site: '// s2_acc += mins*bsums; independent of the dpbusd results, so it runs here instead of in the / band pass: the band pass keeps the register budget for the 8-row band' (~:169-170). The dependency analysis IS the rule: s2 = mins*bsums needs only weight-row metadata, never the dpbusd accumulator, so hoisting it off-band costs no recomputation and buys the whole band its budget back. REGIME: wide microtiles (16+ rows) on 512-bit ISAs where acc + correction terms exceed the file (16 zmm for the 8-row band). ANTI-REGIME: 128-bit ISAs -- the AVX arm needs no banding (16 xmm live fits comfortably); a correction term that DEPENDS on the MAC results cannot go off-band (it would force a second pass over the same data). KINSHIP: compute-role-split-by-accumulator-pressure (Batch 118) = the SIMDGROUP-role split by the same pressure arithmetic; hoist-row-invariant-scale-to-subblock-epilogue (Batch 186) = the same independent-term placement instinct at the SCALE (constant over the loop -> epilogue) -- this rule places a MAC-INDEPENDENT term OFF-BAND. CITE: ggml-org/llama.cpp @ d834d44e -- ggml/src/ggml-cpu/tiled/tiled-kernel.cpp:91-93 + ~169-170. Batch 187 / Plan 183 / Research 218 (staged S2).".to_string(),
            ref_shape: "// NAIVE: ONE pass over the 16-row microtile holds every\n// accumulator the epilogue needs -- acc + s1_acc + s2_acc -- so the\n// pass carries more live vectors than the register file and the\n// allocator spills around the MAC body.\nconst KL: usize = 32;\nconst NB: usize = 8;\n\npub fn microtile_one_pass(\n    codes: &[[u8; KL]],\n    acts: &[i8; KL],\n    scales: &[[i8; NB]],\n    mins_bsums: &[[i32; NB]],\n    rows: usize,\n    out: &mut [f32],\n) {\n    for r in 0..rows {\n        let mut acc: i32 = 0; // the MAC accumulator\n        let mut s1: i32 = 0;  // scale accumulator (rides the MAC pass)\n        let mut s2: i32 = 0;  // min correction -- INDEPENDENT of acc\n        for e in 0..KL {\n            acc += i32::from(codes[r][e]) * i32::from(acts[e]);\n        }\n        for s in 0..NB {\n            s1 += i32::from(scales[r][s]);\n            s2 += mins_bsums[r][s]; // held live through the whole pass\n        }\n        out[r] = f32::from(s1) * f32::from(acc) - f32::from(s2);\n    }\n}".to_string(),
            opt_pattern: "// OPT: the 16-row microtile runs as TWO 8-row BAND passes --\n// each band holds only acc + s1 (16 vectors, fits the file) -- and\n// the MAC-INDEPENDENT s2 correction computes AFTER its band pass:\n// zero pressure on the band, zero recomputation.\nconst KL: usize = 32;\nconst NB: usize = 8;\nconst BAND: usize = 8;\n\nfn band_pass(\n    codes: &[[u8; KL]],\n    acts: &[i8; KL],\n    scales: &[[i8; NB]],\n    acc: &mut [i32; BAND],\n    s1: &mut [i32; BAND],\n) {\n    for r in 0..BAND {\n        let mut a: i32 = 0;\n        let mut sc: i32 = 0;\n        for e in 0..KL {\n            a += i32::from(codes[r][e]) * i32::from(acts[e]);\n        }\n        for s in 0..NB {\n            sc += i32::from(scales[r][s]);\n        }\n        acc[r] = a;\n        s1[r] = sc;\n    }\n}\n\nfn offband_correction(mins_bsums: &[[i32; NB]], s2: &mut [i32; BAND]) {\n    // independent of the MAC results: runs after the band pass\n    for r in 0..BAND {\n        let mut v: i32 = 0;\n        for s in 0..NB {\n            v += mins_bsums[r][s];\n        }\n        s2[r] = v;\n    }\n}\n\npub fn microtile_banded(\n    codes: &[[u8; KL]],\n    acts: &[i8; KL],\n    scales: &[[i8; NB]],\n    mins_bsums: &[[i32; NB]],\n    rows: usize,\n    out: &mut [f32],\n) {\n    let mut acc = [0i32; BAND];\n    let mut s1 = [0i32; BAND];\n    let mut s2 = [0i32; BAND];\n    for band in 0..rows / BAND {\n        let base = band * BAND;\n        band_pass(&codes[base..base + BAND], acts, &scales[base..base + BAND], &mut acc, &mut s1);\n        offband_correction(&mins_bsums[base..base + BAND], &mut s2);\n        for r in 0..BAND {\n            out[base + r] = f32::from(s1[r]) * f32::from(acc[r]) - f32::from(s2[r]);\n        }\n    }\n}".to_string(),
        },

        // ── E: chunk size starts at the macrotile and HALVES while the
        // chunk count cannot saturate the cores, FLOORED at the microtile;
        // first chunk pre-assigned by thread id, dense path atomic
        // work-stealing vs the MoE path's static uniform-cost split. ───
        KernelRule {
            rule_id: "chunk-downsize-work-stealing-microtile-floor".to_string(),
            gpu_concept: "MECHANISM (parallel-grain selection): start the parallel chunk size at one macrotile and HALVE it while the chunk count cannot saturate the cores (nchunk0 * nchunk1 < nth * 4), FLOORED at the microtile size -- chunks below the tile break the tiling invariants, so the floor is load-bearing, not a tuning knob. Then assign work by THREAD-ID PRE-ASSIGNMENT (every thread starts at its own index, so the first unprocessed chunk is nth -- zero coordination for the first wave) and let the dense path steal remaining chunks through an ATOMIC counter, while the MoE path keeps a STATIC uniform-cost split (per-group arithmetic split). SOURCE (ggml-org/llama.cpp @ d834d44e, tiled.cpp, verbatim): '// Step down chunk size if too few chunks to saturate cores, minimum is microtile size' + 'while (nchunk0 * nchunk1 < nth * 4 && chunk_size > 16) { chunk_size = chunk_size / 2; ... }' (tiled.cpp:1103-1104, the 16 floor = the microtile edge) + the pre-assignment: '// Every thread starts at ith, so the first unprocessed chunk is nth. This saves a bit of coordination right at the start.' (~:1082-1083, chunk_set(threadpool, nth)). The 4x multiplier is the saturation target (each thread should own ~4 chunks so stragglers re-balance). REGIME: many-core boxes where a fixed macrotile chunk count under-fills the machine; irregular per-chunk cost (the atomic steal re-balances). ANTI-REGIME: huge workloads -- the fixed chunk count already saturates, and counter traffic is pure overhead (the source keeps fixed chunks there); uniform-cost work where the static split needs no steal at all (the MoE path). KINSHIP: fwht-wide-block-row-per-threadgroup-exchange-ladder (Batch 116) = the same beyond-budget escalation ladder shape at the exchange tier; dynamic-work-parallelism-ladder (rust_perf) = the HOST-side queue-structure ladder -- this is the KERNEL-side chunk-grain ladder, cite as kinship not duplicate. CITE: ggml-org/llama.cpp @ d834d44e -- ggml/src/ggml-cpu/tiled/tiled.cpp:1082-1083 + 1096-1106. Batch 187 / Plan 183 / Research 218 (staged S3).".to_string(),
            ref_shape: "// NAIVE: a FIXED chunk size chosen once (one macrotile per\n// chunk). On a many-core box the chunk count never saturates the\n// machine and the tail threads idle; shrunken without a floor, chunks\n// below the microtile break the tiling invariants.\nconst MACROTILE: usize = 256;\n\npub fn parallel_chunks_fixed(nr0: usize, nr1: usize, nth: usize) -> Vec<(usize, usize)> {\n    let chunk = MACROTILE; // fixed forever: never re-sized to the core count\n    let n0 = nr0.div_ceil(chunk);\n    let n1 = nr1.div_ceil(chunk);\n    let mut chunks = Vec::new();\n    for c0 in 0..n0 {\n        for c1 in 0..n1 {\n            chunks.push((c0 * chunk, c1 * chunk));\n        }\n    }\n    // nth = 32 threads, 6 chunks: 26 threads idle for the whole kernel\n    let _ = nth;\n    chunks\n}".to_string(),
            opt_pattern: "// OPT: start at the macrotile, HALVE while the chunk count\n// cannot saturate the cores (n0*n1 < nth*4), FLOOR at the microtile --\n// and pre-assign thread i to chunk i so the first wave costs zero\n// coordination; remaining chunks go through an atomic work counter.\nconst MACROTILE: usize = 256;\nconst MICROTILE: usize = 16; // the load-bearing floor\n\npub fn chunk_size_for(nr0: usize, nr1: usize, nth: usize) -> usize {\n    let mut chunk = MACROTILE;\n    let mut n0 = nr0.div_ceil(chunk);\n    let mut n1 = nr1.div_ceil(chunk);\n    while n0 * n1 < nth * 4 && chunk > MICROTILE {\n        chunk /= 2; // step down: too few chunks to saturate cores\n        n0 = nr0.div_ceil(chunk);\n        n1 = nr1.div_ceil(chunk);\n    }\n    chunk // never below the microtile: tiling invariants hold\n}\n\npub fn chunk_count(nr0: usize, nr1: usize, chunk: usize) -> usize {\n    nr0.div_ceil(chunk) * nr1.div_ceil(chunk)\n}\n\n/// The dense path: thread `ith` claims chunk `ith` first, then steals\n/// from the shared counter (the first unprocessed chunk is `nth`).\npub fn first_chunk_for(ith: usize) -> usize {\n    ith\n}\n\npub fn steal_next(counter: &std::sync::atomic::AtomicUsize, total: usize) -> Option<usize> {\n    use std::sync::atomic::Ordering::Relaxed;\n    let c = counter.fetch_add(1, Relaxed);\n    if c < total {\n        Some(c)\n    } else {\n        None\n    }\n}".to_string(),
        },

        // ── B: 16-entry byte-LUT code expansion via ONE shuffle per 16
        // codes at unpack; the +128 activation bias is FOLDED INTO the
        // table entries. ──────────────────────────────────────────────
        KernelRule {
            rule_id: "lut16-pshufb-byte-expansion-at-stage".to_string(),
            gpu_concept: "MECHANISM (code expansion): expand 16 quantized codes through a 16-ENTRY byte LUT with ONE table-indexing shuffle at the unpack/stage -- the LUT IS the shuffle table and the packed codes ARE the lane indices -- instead of per-element nibble splits with branchy per-code lookups; and fold any per-element ACTIVATION BIAS (+128) INTO the table entries up front so the expansion is a plain lookup with no separate bias pass. SOURCE (ggml-org/llama.cpp @ d834d44e, tiled-kernel.h + tiled.cpp, verbatim): '// 16-entry byte LUT: dst[j] = lut[src[j]] (16 bytes)' + '_mm_shuffle_epi8(_mm_loadu_si128(lut), _mm_loadu_si128(src))' (tiled-kernel.h:92-95 -- one shuffle produces 16 expanded bytes) + the fold: '// LUT values are stored as kvalues + 128 so the +128 shift the kernel applies to / the activations cancels against the bsums correction (BIAS = 128)' (tiled.cpp:234-236, '+128 is folded into the table up front so the expansion is a plain lookup'). The 16-entry bound is structural: a shuffle indexes bytes mod 16, so a 16-entry table needs no masking and no gather. REGIME: quant formats whose codes index a SMALL fixed table (4-bit grids, 16-entry kvalues); expansion happens per block at the stage where the codes are contiguous. ANTI-REGIME: tables >16 entries -- the shuffle cannot index them, a gather (indexed load per lane) is the shape; formats whose decode is arithmetic (shift/sign masks) -- no table exists to fold the bias into. KINSHIP: packed-code-cpasync-stage-per-use-prmt-decode = the GPU (prmt) tier of the same shuffle-decode family -- this is the CPU (pshufb) tier, cite as kinship not duplicate. CITE: ggml-org/llama.cpp @ d834d44e -- ggml/src/ggml-cpu/tiled/tiled-kernel.h:92-95 + tiled.cpp:234-236. Batch 187 / Plan 183 / Research 218 (staged S4).".to_string(),
            ref_shape: "// NAIVE: LUT expansion decodes per element -- nibble split, a\n// table load per code, and the +128 activation bias applied in a\n// SEPARATE pass over the expanded values.\nconst KVAL: [i8; 16] = [1, 7, -3, 5, -8, 2, 6, -6, 3, -1, 8, -5, 4, -7, -2, -4];\n\npub fn expand_naive(packed: &[u8]) -> Vec<i8> {\n    let mut out = Vec::with_capacity(packed.len() * 2);\n    for &byte in packed {\n        for code in [byte & 0x0F, byte >> 4] {\n            let v = KVAL[code as usize];\n            out.push(v);\n        }\n    }\n    // the +128 bias rides a SECOND pass ...\n    out.iter().map(|&v| v + 128).collect()\n}".to_string(),
            opt_pattern: "// OPT: the bias is FOLDED INTO the table at build time (values\n// stored as kvalues + 128, canceling the kernel's +128 shift against\n// the bsums correction), and 16 codes expand through ONE table-index\n// shuffle: the table IS the shuffle table, the codes ARE the indices.\nconst LANES: usize = 16;\n\n/// Build the folded table ONCE: entry i = kvalues[i] + 128 (BIAS =\n/// 128), so expansion needs no separate bias pass.\npub fn folded_table(kvalues: &[i8; LANES]) -> [u8; LANES] {\n    let mut lut = [0u8; LANES];\n    for i in 0..LANES {\n        lut[i] = (i32::from(kvalues[i]) + 128) as u8;\n    }\n    lut\n}\n\n/// One \"shuffle\" over 16 packed codes (portable spelling of a byte\n/// table-index shuffle): dst[j] = lut[src[j]] for 16 lanes at once.\npub fn expand16(lut: &[u8; LANES], codes: &[u8; LANES]) -> [u8; LANES] {\n    let mut dst = [0u8; LANES];\n    for j in 0..LANES {\n        dst[j] = lut[codes[j] as usize]; // codes < 16: no masking\n    }\n    dst\n}\n\n/// The bit unpacker hands over code bytes; expansion runs ONE shuffle\n/// per 16 codes with the folded table -- no per-code loop, no bias pass.\npub fn expand_codes(lut: &[u8; LANES], codes: &[u8]) -> Vec<u8> {\n    let mut out = Vec::with_capacity(codes.len());\n    for group in codes.chunks_exact(LANES) {\n        let mut buf = [0u8; LANES];\n        buf.copy_from_slice(group);\n        out.extend_from_slice(&expand16(lut, &buf));\n    }\n    out\n}".to_string(),
        },

        // ── B: grid+sign expansion -- broadcast sign bytes via a shuffle,
        // build the all-ones-per-set-bit mask in ONE instruction when GFNI
        // is present (the cmpeq form is the portable fallback); negation
        // is branch-free (v ^ mask - mask). ────────────────────────────
        KernelRule {
            rule_id: "gfni-sign-mask-expand-cmpeq-fallback".to_string(),
            gpu_concept: "MECHANISM (sign-bit expansion): expand a packed grid+sign code -- broadcast the per-group SIGN BYTES across their lanes with a byte shuffle, then build the all-ones-per-set-bit mask in ONE instruction when GFNI is available (the affine instruction performs the and+compare in a single op against the 0x8040201008040201 selector matrix); the portable FALLBACK is the two-op compare form ((sv & sel) == sel); negation is then BRANCH-FREE (v ^ mask - mask, the classic all-ones conditional-negate) and +128 gives the biased output code. SOURCE (ggml-org/llama.cpp @ d834d44e, tiled-kernel.h, verbatim): '// 0xFF in every lane whose sign bit is set; GFNI does the and+compare in one instruction' + '#ifdef __GFNI__ ... _mm256_gf2p8affine_epi64_epi8(sel, sv, 0) #else ... _mm256_cmpeq_epi8(_mm256_and_si256(sv, sel), sel)' (tiled-kernel.h:105-116) + '// v ^ mask - mask negates the signed lanes (v elsewhere); + 128 gives the biased code' (~:115). One instruction vs a per-bit test-branch-negate chain across 32 lanes; the fallback keeps the whole lane-wide shape on non-GFNI parts. REGIME: ternary/grid quant formats that pack a sign bitmap alongside the code (the sign decides per-lane negate); x86 with compile-time GFNI detection. ANTI-REGIME: non-x86 -- the cmpeq form IS the portable version (ship it as the fallback arm, never as a third implementation); scalar tails -- the lane-wide shape needs a full vector of codes. KINSHIP: activation-bitplane-popcount-word-dot (Batch 116) = the same pack-signs-as-bits discipline at the DOT level; lut16-pshufb-byte-expansion-at-stage (this batch) = the sibling code-expansion shape (table-index shuffle vs sign-mask expand) -- compose at the same stage. CITE: ggml-org/llama.cpp @ d834d44e -- ggml/src/ggml-cpu/tiled/tiled-kernel.h:103-116. Batch 187 / Plan 183 / Research 218 (staged S5).".to_string(),
            ref_shape: "// NAIVE: sign expansion extracts bits ONE at a time -- a shift,\n// a test, and a branch per lane, then a conditional negate per\n// element. 32 lanes = 32 dependent test/branch chains.\npub fn expand_signs_naive(values: &mut [i8], sign_words: &[u32]) {\n    for (l, v) in values.iter_mut().enumerate() {\n        let bit = (sign_words[l / 32] >> (l % 32)) & 1;\n        if bit == 1 {\n            *v = -*v; // branch per lane\n        }\n    }\n}".to_string(),
            opt_pattern: "// OPT: the sign mask for ALL lanes is built in vector shape --\n// broadcast the 4 sign bytes across their lanes (a byte shuffle), then\n// ONE mask op: the GFNI affine form (and+compare in one instruction\n// against the 0x8040201008040201 selector) when present, the portable\n// cmpeq fallback otherwise. Negation is branch-free: x ^ mask - mask.\nconst LANES: usize = 32;\n\n/// Lane l takes sign byte l / 8 (the shuffle-broadcast step).\nfn broadcast_signs(sign_word: u32) -> [u8; LANES] {\n    let bytes = sign_word.to_le_bytes();\n    let mut sv = [0u8; LANES];\n    for l in 0..LANES {\n        sv[l] = bytes[l / 8];\n    }\n    sv\n}\n\n/// The per-lane selector bit for lane l within its byte.\nfn sel_lanes() -> [u8; LANES] {\n    let mut sel = [0u8; LANES];\n    for l in 0..LANES {\n        sel[l] = 1u8 << (l % 8); // 0x01, 0x02, ... 0x80 repeating\n    }\n    sel\n}\n\n/// mask = 0xFF where the lane's sign bit is set. `gfni` selects the\n/// one-instruction affine form; the fallback is (sv & sel) == sel.\nfn sign_mask(sv: &[u8; LANES], sel: &[u8; LANES], gfni: bool) -> [u8; LANES] {\n    let mut mask = [0u8; LANES];\n    for l in 0..LANES {\n        if gfni {\n            // GFNI: the and+compare in ONE instruction (gf2p8affine with\n            // the bit-matrix constant -- spelled portably here)\n            let bit_set = (sv[l] & sel[l]) == sel[l];\n            mask[l] = if bit_set { 0xFF } else { 0x00 };\n        } else {\n            mask[l] = if (sv[l] & sel[l]) == sel[l] { 0xFF } else { 0x00 };\n        }\n    }\n    mask\n}\n\npub fn expand_signs(values: &mut [i8], sign_word: u32, gfni: bool) {\n    let sv = broadcast_signs(sign_word);\n    let sel = sel_lanes();\n    let mask = sign_mask(&sv, &sel, gfni);\n    for (l, v) in values.iter_mut().enumerate() {\n        let m = i8::from(mask[l] != 0);\n        // branch-free negate: x ^ m - m == -x when m == -1, x when 0\n        *v = (*v ^ m).wrapping_sub(m);\n    }\n}".to_string(),
        },
    ]
}
